    vocab=[("respeto", "tratar bien a los demás y lo que les pertenece"), ("escuchar", "poner atención cuando otro habla"), ("turno", "momento que le toca a cada uno"), ("cortesía", "buenos modales, como saludar y agradecer"), ("pertenencia", "cosa que es de alguien")],
