    context=[ex("En el recreo, Rosa quiere jugar al elástico. Hay dos niñas esperando su turno y Rosa llega después. Dice: «Yo estaba antes». ¿Qué acción de respeto corresponde?", "Ir al final y esperar su turno", "Llegó después que las otras dos.")],
    selfcheck=[ex("Escribe una acción que muestre respeto.", "Por ejemplo escuchar, esperar el turno o saludar", "Son acciones que se pueden ver."), ex("¿Se puede mostrar respeto sólo con palabras?", "No; también con acciones", "Hay que hacerlo."), ex("¿Qué se dice al pedir algo con cortesía?", "Por favor", "Es una palabra de cortesía.")],
